 stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-hammer h-10 w-10 text-gold" aria-hidden="true"><path d="m15 12-9.373 9.373a1 1 0 0 1-3.001-3L12 9"></path><path d="m18 15 4-4"></path><path d="m21.5 11.5-1.914-1.914A2 2 0 0 1 19 8.172v-.344a2 2 0 0 0-.586-1.414l-1.657-1.657A6 6 0 0 0 12.516 3H9l1.243 1.243A6 6 0 0 1 12 8.485V10l2 2h1.172a2 2 0 0 1 1.414.586L18.5 14.5"></path></svg><span class="text-[15px] font-semibold text-ink">Implementation First</span></li><li class="flex flex-col items-center gap-4 border border-ink-tint bg-card p-6 text-center transition-colors hover:border-gold"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-rocket h-10 w-10 text-gold" aria-hidden="true"><path d="M12 15v5s3.03-.55 4-2c1.08-1.62 0-5 0-5"></path><path d="M4.5 16.5c-1.5 1.26-2 5-2 5s3.74-.5 5-2c.71-.84.7-2.13-.09-2.91a2.18 2.18 0 0 0-2.91-.09"></path><path d="M9 12a22 22 0 0 1 2-3.95A12.88 12.88 0 0 1 22 2c0 2.72-.78 7.5-6 11a22.4 22.4 0 0 1-4 2z"></path><path d="M9 12H4s.55-3.03 2-4c1.62-1.08 5 .05 5 .05"></path></svg><span class="text-[15px] font-semibold text-ink">Continuous Growth</span></li></ul></section></div></section><section class="section-y border-b border-ink-tint bg-ink-wash"><div class="shell"><section data-visible="false" class="reveal max-w-2xl"><h2 class="font-display text-4xl font-semibold tracking-tight text-ink md:text-[3rem]">What Makes SBC Different</h2></section><div class="mt-8 grid gap-5 sm:grid-cols-2"><section data-visible="false" class="reveal "><article class="flex h-full flex-col border border-ink-tint bg-card p-5 transition-colors hover:border-gold/60"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-shield-check size-6 text-gold" aria-hidden="true"><path d="M20 13c0 5-3.5 7.5-7.66 8.95a1 1 0 0 1-.67-.01C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.24-2.72a1.17 1.17 0 0 1 1.52 0C14.51 3.81 17 5 19 5a1 1 0 0 1 1 1z"></path><path d="m9 12 2 2 4-4"></path></svg><h3 class="mt-4 font-display text-lg font-semibold leading-snug text-ink">Implementation Focused</h3><p class="mt-2 flex-1 text-[16px] leading-relaxed text-charcoal">We don&#x27;t leave after the report. We stay until results are delivered and measurable outcomes are achieved.</p></article></section><section data-visible="false" class="reveal "><article class="flex h-full flex-col border border-ink-tint bg-card p-5 transition-colors hover:border-gold/60"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-target size-6 text-gold" aria-hidden="true"><circle cx="12" cy="12" r="10"></circle><circle cx="12" cy="12" r="6"></circle><circle cx="12" cy="12" r="2"></circle></svg><h3 class="mt-4 font-display text-lg font-semibold leading-snug text-ink">Structured Approach</h3><p class="mt-2 flex-1 text-[16px] leading-relaxed text-charcoal">Every engagement follows a proven methodology — GAP360™ for business, structured frameworks for institutions.</p></article></section><section data-visible="false" class="reveal "><article class="flex h-full flex-col border border-ink-tint bg-card p-5 transition-colors hover:border-gold/60"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-trending-up size-6 text-gold" aria-hidden="true"><path d="M16 7h6v6"></path><path d="m22 7-8.5 8.5-5-5L2 17"></path></svg><h3 class="mt-4 font-display text-lg font-semibold leading-snug text-ink">Domain Expertise</h3><p class="mt-2 flex-1 text-[16p